package com.amdocs.telecom.main;import com.amdocs.telecom.util.DBConnection;import com.amdocs.telecom.security.PasswordUtil;import java.sql.*;public final class Seeder{public static void seed()throws Exception{try(Connection c=DBConnection.getInstance().get()){merge(c,"MERGE INTO customers KEY(customer_id) VALUES('CUST100245','CN100245','Demo Customer','customer@example.com','9999999999','ENTERPRISE','Pune','ACTIVE',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)");merge(c,"MERGE INTO telecom_services KEY(service_id) VALUES('SVC1001','ENT-001','Enterprise Connectivity','ENTERPRISE_CONNECTIVITY','CUST100245',CURRENT_DATE,'ACTIVE',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)");String[] es={"'ENG1008','E1008','Engineer 1008','Core Network','West',9,TRUE,2","'ENG1015','E1015','Engineer 1015','RAN','North',7,TRUE,4","'ENG1021','E1021','Engineer 1021','Broadband','South',6,TRUE,1","'ENG1030','E1030','Engineer 1030','IP Network','West',10,TRUE,3"};for(String e:es)merge(c,"MERGE INTO network_engineers KEY(engineer_id) VALUES("+e+",CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)");String[] sla={"'CRITICAL',15,120","'HIGH',30,240","'MEDIUM',120,720","'LOW',480,2880"};for(String x:sla)merge(c,"MERGE INTO sla_configuration KEY(priority) VALUES("+x+")");user(c,"customer","CUSTOMER","CUST100245","Customer@123");user(c,"desk","SERVICE_DESK",null,"Desk@123");user(c,"engineer","NETWORK_ENGINEER","ENG1008","Engineer@123");user(c,"manager","NETWORK_MANAGER",null,"Manager@123");}}private static void user(Connection c,String u,String role,String ref,String password)throws SQLException{String hash=PasswordUtil.hash(password);try(PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM users WHERE username=?")){p.setString(1,u);try(ResultSet r=p.executeQuery()){r.next();if(r.getInt(1)>0){try(PreparedStatement up=c.prepareStatement("UPDATE users SET password_hash=?,role=?,ref_id=?,updated_at=CURRENT_TIMESTAMP WHERE username=?")){up.setString(1,hash);up.setString(2,role);up.setString(3,ref);up.setString(4,u);up.executeUpdate();}return;}}}try(PreparedStatement p=c.prepareStatement("INSERT INTO users(username,password_hash,role,ref_id)VALUES(?,?,?,?)")){p.setString(1,u);p.setString(2,hash);p.setString(3,role);p.setString(4,ref);p.executeUpdate();}}private static void merge(Connection c,String q)throws SQLException{try(Statement s=c.createStatement()){s.executeUpdate(q);}}}
